/// number of members of an enum table
pub fn table_len(t: u32) -> usize {
    match t {
        0 => 12,
        1 => 7,
        2 => 2,
        3 => 3,
        4 => 2,
        5 => 10,
        _ => 0,
    }
}

/// `names[k] == s` for an enum table (member `k` has value `k`)
pub fn table_name_is(t: u32, k: usize, s: &[u32]) -> bool {
    match t {
        0 => match k {
            0 => str_eq(s, b"General"),
            1 => str_eq(s, b"Editor"),
            2 => str_eq(s, b"Metadata"),
            3 => str_eq(s, b"Difficulty"),
            4 => str_eq(s, b"Events"),
            5 => str_eq(s, b"TimingPoints"),
            6 => str_eq(s, b"Colours"),
            7 => str_eq(s, b"HitObjects"),
            8 => str_eq(s, b"Variables"),
            9 => str_eq(s, b"Fonts"),
            10 => str_eq(s, b"CatchTheBeat"),
            11 => str_eq(s, b"Mania"),
            _ => false,
        },
        1 => match k {
            0 => str_eq(s, b"Background"),
            1 => str_eq(s, b"Video"),
            2 => str_eq(s, b"Break"),
            3 => str_eq(s, b"Colour"),
            4 => str_eq(s, b"Sprite"),
            5 => str_eq(s, b"Sample"),
            6 => str_eq(s, b"Animation"),
            _ => false,
        },
        2 => match k {
            0 => str_eq(s, b"MaximumAchievable"),
            1 => str_eq(s, b"Standard"),
            _ => false,
        },
        3 => match k {
            0 => str_eq(s, b"Horizontal"),
            1 => str_eq(s, b"Vertical"),
            2 => str_eq(s, b"Both"),
            _ => false,
        },
        4 => match k {
            0 => str_eq(s, b"Clockwise"),
            1 => str_eq(s, b"Counterclockwise"),
            _ => false,
        },
        5 => match k {
            0 => str_eq(s, b"Linear"),
            1 => str_eq(s, b"Gravity"),
            2 => str_eq(s, b"InOut1"),
            3 => str_eq(s, b"InOut2"),
            4 => str_eq(s, b"Accelerate1"),
            5 => str_eq(s, b"Accelerate2"),
            6 => str_eq(s, b"Accelerate3"),
            7 => str_eq(s, b"Decelerate1"),
            8 => str_eq(s, b"Decelerate2"),
            9 => str_eq(s, b"Decelerate3"),
            _ => false,
        },
        _ => false,
    }
}

